fn binary_search(a: &[int], key: int) -> (index: i32)
    requires
        sorted(a@, 0, a.len() - 1),
        a.len() < i32::MAX as usize,
    ensures
        index >= 0 ==> index < a.len() as i32 && a[index as int] == key,
        index < 0 ==> forall|k: int| 0 <= k && k < a.len() ==> a[k] != key,
{

answer:
let mut low = 0;
    let mut high = a.len();
    while low < high
        invariant
            0 <= low && low <= high && high <= a.len(),
            forall|i: int| 0 <= i && i < a.len() && !(low <= i && i < high) ==> a[i] != key,
            sorted(a@, 0, a.len() - 1),
            a.len() < i32::MAX as usize,
        decreases high - low,
    {
        let mid = (low + high) / 2;
        assert(low <= mid && mid < high);
        assert(mid < a.len());
        if a[mid] < key {
            low = mid + 1;
        } else if key < a[mid] {
            high = mid;
        } else {
            return mid as i32;
        }
    }
    -1
}

