fn is_equal_func(s: &[char], t: &[char]) -> (result: bool)
    requires
        s.len() == t.len(),
    ensures
        (s@ == t@) == result,
{
    let mut result = true;
    for i in 0..s.len()
        invariant
            0 <= i <= s.len(),
            s.len() == t.len(),
            result ==> (forall|j: int| 0 <= j && j < i ==> s[j] == t[j]),
            !result ==> (exists|j: int| 0 <= j && j < i && s[j] != t[j]),
    {
        if s[i] != t[i] {
            result = false;
        }
    }
    if result {
        assert(forall|i: int| 0 <= i && i < s.len() ==> s[i] == t[i]);
    } else {
        assert(exists|i: int| 0 <= i && i < s.len() && s[i] != t[i]);
    }
    assert((s@ == t@) == result) by {
        if result {
            assert(forall|i: int| 0 <= i && i < s.len() ==> s[i] == t[i]);
            assert(s@ == t@);
            assert(result == (s@ == t@));
        } else {
            assert(exists|i: int| 0 <= i && i < s.len() && s[i] != t[i]);
            assert(s@ != t@);
            assert(result == (s@ == t@));
        }
    }
    result
}

