spec fn peek_sum(v: Seq<int>, i: int) -> int
    recommends
        0 <= i && i <= v.len(),
    decreases i,
{
    if i <= 1 {
        v[0]
    } else if is_peak(v, i - 1) {
        v[i - 1] + peek_sum(v, i - 1)
    } else {
        peek_sum(v, i - 1)
    }
}

fn m_peak_sum(v: &Vec<int>) -> (sum: int)
    requires
        v.len() > 0,
        v.len() < 1000,
    ensures
        sum == peek_sum(v@, v.len() as int),
{

answer:
let mut i: usize = 1;
    let mut sum: int = v[0];
    let mut lmax: int = v[0];
    while i < v.len()
        invariant
            0 < i && i <= v.len(),
            exists|k: int| 0 <= k && k < i as int && lmax == v[k],
            forall|k: int| 0 <= k && k < i as int ==> lmax >= v[k],
            sum == peek_sum(v@, i as int),
        decreases v.len() - i,
    {
        if v[i] >= lmax {
            sum = sum + v[i];
            lmax = v[i];
        }
        i = i + 1;
    }
    assert(sum == peek_sum(v@, v.len() as int));
    sum
}

