    forall|i: int, j: int| 0 <= i < j && j < nums.len() ==> nums[i] != nums[j]
}

fn contains_duplicate(nums: Vec<int>) -> (result: bool)
    requires
        1 <= nums.len() && nums.len() <= 100000,
        forall|i: int| 0 <= i < nums.len() ==> nums[i] >= -1000000000 && nums[i] <= 1000000000,
    ensures
        result <==> distinct_elements(nums@),
{

answer:
let mut i = 0;
    let mut s: Vec<int> = Vec::new();
    while i < nums.len()
        invariant
            i <= nums.len(),
            s.len() == i,
            forall|j: int| 0 <= j < i ==> s[j as int] == nums[j as int],
            forall|j: int, k: int| 0 <= j < i && 0 <= k < i ==> j != k ==> s[j as int] != s[k as int],
            distinct_elements(s@),
        decreases
            nums.len() as int - i,
    {
        let num = nums[i];
        let mut found = false;
        let mut j = 0;
        while j < s.len()
            invariant
                0 <= j && j <= s.len(),
                !found ==> (forall|k: int| 0 <= k && k < j ==> s[k as int] != num),
                found ==> (exists|k: int| 0 <= k && k < j && s[k as int] == num),
        decreases
            s.len() as int - j,
    {
            if num == s[j] {
                found = true;
            }
            j = j + 1;
        }
        if found {
            return false;
        }
        s.push(num);
        i = i + 1;
    }
    true
}

