            blood.len() as i32 - index,
    {
        if blood[index as usize] == key {
            return index;
        }
        index = index + 1;
    }
    -1
}

let mut min_second_index = 0;
    for i in 1..s.len()
        invariant
            0 <= i <= s.len(),
            0 <= min_second_index < i,
            forall|j: nat| 0 <= j < i ==> s[min_second_index as int][1] <= s[j as int][1],
            s.len() > 0,
            forall|j: nat| j < s.len() ==> s[j as int].len() >= 2,
    {
        if s[i][1] < s[min_second_index][1] {
            min_second_index = i;
        }
    }
    s[min_second_index][0]
}
